import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32

__global__ void matmul_kernel_shared(const float* A, const float* B, float* C, int N) {
    __shared__ float a_tile[TILE_DIM][TILE_DIM];
    __shared__ float b_tile[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    float sum = 0.0f;

    for (int tile_idx = 0; tile_idx < N / TILE_DIM; ++tile_idx) {
        // Load tiles into shared memory
        int a_row = row;
        int a_col = tile_idx * TILE_DIM + threadIdx.x;
        if (a_row < N && a_col < N) {
            a_tile[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            a_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        int b_row = tile_idx * TILE_DIM + threadIdx.y;
        int b_col = col;
        if (b_row < N && b_col < N) {
           b_tile[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
           b_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_DIM; ++k) {
            sum += a_tile[threadIdx.y][k] * b_tile[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are not compatible for multiplication");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const dim3 blockSize(TILE_DIM, TILE_DIM);
    const dim3 gridSize((N + TILE_DIM - 1) / TILE_DIM, (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel_shared<<<gridSize, blockSize>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
