#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define THREAD_WORK 4

__global__ void matmul_kernel_deeper(const float* A, const float* B, float* C, int N) {
    __shared__ float a_tile[TILE_DIM][TILE_DIM];
    __shared__ float b_tile[TILE_DIM][TILE_DIM];

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Each thread computes a THREAD_WORK x THREAD_WORK sub-matrix of C
    float c_sub_tile[THREAD_WORK][THREAD_WORK] = {0.0f};

    // Starting row and column for the thread's sub-matrix
    int c_start_row = block_row * TILE_DIM + thread_row * THREAD_WORK;
    int c_start_col = block_col * TILE_DIM + thread_col * THREAD_WORK;

    for (int tile_idx = 0; tile_idx < N / TILE_DIM; ++tile_idx) {
        // Load tiles into shared memory
        // Each thread now loads THREAD_WORK * THREAD_WORK elements
        for(int i = 0; i < THREAD_WORK; ++i) {
            for (int j = 0; j < THREAD_WORK; ++j) {
                int a_load_row = c_start_row + i;
                int a_load_col = tile_idx * TILE_DIM + thread_col * THREAD_WORK + j;
                 if(a_load_row < N && a_load_col < N){
                    a_tile[thread_row * THREAD_WORK + i][thread_col * THREAD_WORK + j] = A[a_load_row * N + a_load_col];
                 } else {
                    a_tile[thread_row * THREAD_WORK + i][thread_col * THREAD_WORK + j] = 0.0f;
                 }


                int b_load_row = tile_idx * TILE_DIM + thread_row * THREAD_WORK + i;
                int b_load_col = c_start_col + j;

                if(b_load_row < N && b_load_col < N){
                    b_tile[thread_row * THREAD_WORK + i][thread_col * THREAD_WORK + j] = B[b_load_row * N + b_load_col];
                } else {
                    b_tile[thread_row * THREAD_WORK + i][thread_col * THREAD_WORK + j] = 0.0f;
                }
            }
        }
        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_DIM; ++k) {
            #pragma unroll
            for (int i = 0; i < THREAD_WORK; ++i) {
                #pragma unroll
                for (int j = 0; j < THREAD_WORK; ++j) {
                    c_sub_tile[i][j] += a_tile[thread_row * THREAD_WORK + i][k] * b_tile[k][thread_col * THREAD_WORK + j];
                }
            }
        }
        __syncthreads();
    }

    // Write the results to global memory
    for (int i = 0; i < THREAD_WORK; ++i) {
        for (int j = 0; j < THREAD_WORK; ++j) {
            int c_write_row = c_start_row + i;
            int c_write_col = c_start_col + j;
            if (c_write_row < N && c_write_col < N) {
                C[c_write_row * N + c_write_col] = c_sub_tile[i][j];
            }
        }
    }
}


